import{_ as a,o as t,c as s,a2 as d}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Referencia de configuración","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/index.md","filePath":"es-ES/user-guide/settings/index.md","lastUpdated":1785993908000}'),r={name:"es-ES/user-guide/settings/index.md"};function i(n,e,o,l,c,u){return t(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="referencia-de-configuracion" tabindex="-1">Referencia de configuración <a class="header-anchor" href="#referencia-de-configuracion" aria-label="Permalink to &quot;Referencia de configuración&quot;">​</a></h1><p>La ventana de configuración se redimensiona y se maximiza como cualquier otra: arrastra sus bordes, usa el botón de maximizar de la barra de título, o haz doble clic en la barra de título. Merece la pena sobre todo en la página de Plugins, que pone una lista de plugins y los ajustes de ese plugin uno al lado del otro y aprovecha el ancho.</p><p>En la barra de título de la ventana de Configuración hay un cuadro de búsqueda. Coincide de forma difusa (la misma coincidencia al estilo fzf que usa la ventana de búsqueda principal, con soporte de alias en pinyin), no solo subcadenas simples, en todas las secciones — incluidas las entradas por plugin bajo Plugins, la subpestaña Acciones de plugins de Atajos. Cada resultado muestra una ruta de migas de pan (por ejemplo, &quot;Índice &gt; Unidades de red&quot;) para que ajustes con el mismo nombre en distintas pestañas se puedan distinguir. Seleccionar un resultado (clic, o Arriba/Abajo para resaltar e Intro) cambia a la sección y pestaña correctas, desplaza el control exacto hasta que sea visible, y hace parpadear brevemente un borde de resaltado a su alrededor.</p><p>Varias secciones (General, Atajos, Índice, Historial, Panel Rápido, Estado del Servicio) se dividen además en su propia fila de subpestañas en la parte superior de la página. Si las etiquetas de las pestañas no caben todas — lo más habitual en inglés, ya que las etiquetas traducidas suelen ser más largas que sus originales en chino — aparecen botones de flecha izquierda/derecha en los extremos de la fila para que el resto siga siendo alcanzable desplazándose, en lugar de quedar simplemente cortado.</p><p>La ventana de Configuración tiene diez secciones en su barra lateral izquierda:</p><table tabindex="0"><thead><tr><th>Sección</th><th>Cubre</th></tr></thead><tbody><tr><td><a href="./service-status.html">Estado del Servicio</a></td><td>Instalación del servicio en segundo plano, y el visor de registros de App/Hook/Service.</td></tr><tr><td><a href="./index-drives.html">Índice</a></td><td>Unidades locales, unidades de red, distribuciones WSL (una vez detectadas), índices de carpetas y reglas de exclusión.</td></tr><tr><td><a href="./general.html">General</a></td><td>Comportamiento de inicio, actualizaciones, idioma, diseño de la barra de búsqueda y tamaño de la ventana de vista previa.</td></tr><tr><td><a href="./hotkeys-page.html">Atajos</a></td><td>Atajos globales, atajos de acción por plugin y la lista negra de procesos.</td></tr><tr><td><a href="./plugins.html">Plugins</a></td><td>Plugins instalados y los interruptores de habilitar/deshabilitar por componente.</td></tr><tr><td><a href="./localsend.html">LocalSend</a></td><td>Configuración de transferencia LAN entre dispositivos para archivos, carpetas y texto plano.</td></tr><tr><td><a href="./favorites.html">Favoritos</a></td><td>Accesos directos con nombre personalizado a carpetas, archivos y URL.</td></tr><tr><td><a href="./history.html">Historial</a></td><td>Historial de búsqueda e historial de palabras clave de la ventana rápida.</td></tr><tr><td><a href="./quick-panel.html">Panel Rápido</a></td><td>El panel flotante acoplado sobre la ventana en primer plano: sus espacios de trabajo, las fuentes de cada uno, las pestañas que aportan los plugins, y a qué aplicaciones pertenece cada espacio.</td></tr><tr><td><a href="./appearance.html">Apariencia</a></td><td>Selector de tema (con una tarjeta de vista previa por tema) y el modo &quot;seguir el claro/oscuro del sistema&quot;. Fijado encima de Acerca de.</td></tr><tr><td><a href="./about.html">Acerca de</a></td><td>Información de versión y comprobación de actualizaciones.</td></tr></tbody></table><p>Cada página de abajo documenta todas las opciones de esa sección, en orden, con su valor predeterminado y cualquier rango válido.</p>',7)])])}const h=a(r,[["render",i]]);export{m as __pageData,h as default};
